mapper.select:
SELECT p.id, p.title, p.content, p.summary, p.cover_image, p.thumbnail, p.category_id, p.author_id, p.status, p.view_count, p.like_count, p.created_at, p.updated_at, p.created_by, p.updated_by, p.deleted_at, c.id as cat_id, c.name as cat_name, c.description as cat_description, u.id as author_user_id, u.username as author_username, u.email as author_email, u.avatar_url as author_avatar_url, (SELECT COUNT(*) FROM comments cm WHERE cm.post_id = p.id AND cm.deleted_at IS NULL) as comment_count FROM posts p LEFT JOIN categories c ON p.category_id = c.id LEFT JOIN users u ON p.author_id = u.id WHERE p.deleted_at IS NULL
AND p.status = #{status}
AND p.status = 'published'
AND p.author_id = #{authorId}
AND p.category_id = #{categoryId}
AND EXISTS (SELECT 1 FROM post_tags pt2 WHERE pt2.post_id = p.id AND pt2.tag_id = #{tagId})
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.created_at DESC

SELECT p.id, p.title, p.content, p.summary, p.cover_image, p.thumbnail, p.category_id, p.author_id, p.status, p.view_count, p.like_count, p.favorite_count, p.created_at, p.updated_at, p.created_by, p.updated_by, p.deleted_at, c.id as cat_id, c.name as cat_name, c.description as cat_description, u.id as author_user_id, u.username as author_username, u.email as author_email, u.avatar_url as author_avatar_url, (SELECT COUNT(*) FROM comments cm WHERE cm.post_id = p.id AND cm.deleted_at IS NULL) as comment_count, CASE WHEN pl.is_like = 1 THEN 1 ELSE 0 END as like_status, CASE WHEN pf.is_favorite = 1 THEN 1 ELSE 0 END as favorite_status FROM posts p LEFT JOIN categories c ON p.category_id = c.id LEFT JOIN users u ON p.author_id = u.id LEFT JOIN post_likes pl ON p.id = pl.post_id AND pl.user_id = #{userId} LEFT JOIN post_favorites pf ON p.id = pf.post_id AND pf.user_id = #{userId} WHERE p.deleted_at IS NULL
AND p.status = #{status}
AND p.status = 'published'
AND p.author_id = #{authorId}
AND p.category_id = #{categoryId}
AND EXISTS (SELECT 1 FROM post_tags pt2 WHERE pt2.post_id = p.id AND pt2.tag_id = #{tagId})
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.created_at DESC

SELECT p.id, p.title, p.summary, p.cover_image, p.thumbnail, p.category_id, p.author_id, p.series_id, p.series_sort, p.status, p.view_count, p.like_count, p.favorite_count, p.created_at, p.updated_at, c.id as cat_id, c.name as cat_name, s.name as series_name, u.id as author_user_id, u.username as author_username, u.avatar_url as author_avatar_url, (SELECT COUNT(*) FROM comments cm WHERE cm.post_id = p.id AND cm.deleted_at IS NULL) as comment_count,
CASE WHEN pl.id IS NOT NULL THEN 1 ELSE 0 END as like_status, CASE WHEN pf.id IS NOT NULL THEN 1 ELSE 0 END as favorite_status
0 as like_status, 0 as favorite_status
FROM posts p LEFT JOIN categories c ON p.category_id = c.id LEFT JOIN post_series s ON p.series_id = s.id AND s.deleted_at IS NULL LEFT JOIN users u ON p.author_id = u.id
LEFT JOIN post_likes pl ON p.id = pl.post_id AND pl.user_id = #{userId} AND pl.is_like = 1 LEFT JOIN post_favorites pf ON p.id = pf.post_id AND pf.user_id = #{userId} AND pf.is_favorite = 1
WHERE p.deleted_at IS NULL
AND p.status = #{status}
AND p.status = 'published'
AND p.category_id = #{categoryId}
AND p.series_id = #{seriesId}
AND EXISTS (SELECT 1 FROM post_tags pt2 WHERE pt2.post_id = p.id AND pt2.tag_id = #{tagId})
AND ( p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM post_tags pt INNER JOIN tags t ON pt.tag_id = t.id WHERE pt.post_id = p.id AND t.name LIKE CONCAT('%', #{keyword}, '%') ) )
AND p.status = #{status}
AND p.author_id = #{authorId}
ORDER BY p.created_at DESC

